mapper.select:
SELECT COALESCE(mg.name, dg.goods_name) AS commonName, dg.common_id AS commonId, dg.goods_id AS goodsId, COALESCE(mg.image, dg.goods_image) AS commonImage, dg.shop_id AS shopId, db.shop_name AS shopName, COALESCE(mg.min_price, dg.goods_price) AS commonPrice, dg.discount_price AS activityPrice, 0 AS commonEvaluate, COALESCE(mg.sale_num, 0) AS commonSalenum, date_format( db.discount_start_time, '%Y-%m-%d %H:%i:%S' ) AS startTime, date_format( db.discount_end_time, '%Y-%m-%d %H:%i:%S' ) AS endTime FROM ${database.prefix.activity}hou_addon_activity_discount_base db INNER JOIN ${database.prefix.activity}hou_addon_activity_discount_goods dg ON db.discount_id = dg.discount_id LEFT JOIN ${database.prefix.goods}hou_mall_goods mg ON dg.common_id = mg.id where db.discount_state in (1,4) and dg.discount_goods_state in (1,4)
and dg.shop_id = #{param.shopId}
and dg.discount_price >= #{param.minPrice,jdbcType=DECIMAL}
and dg.discount_price <= #{param.maxPrice,jdbcType=DECIMAL}
GROUP BY dg.common_id
ORDER BY dg.discount_price desc
ORDER BY dg.discount_price ASC
ORDER BY dg.discount_price ASC

select discount_id, discount_name, discount_start_time, discount_end_time,discount_lower_limit, discount_state, discount_upper_limit from ${database.prefix.activity}hou_addon_activity_discount_base WHERE 1=1
and shop_id = #{param.shopId,jdbcType=INTEGER}
and discount_id = #{param.discountId,jdbcType=INTEGER}
and discount_state = #{param.discountState,jdbcType=INTEGER}
and discount_name LIKE CONCAT('%',#{param.discountName },'%')
order by discount_create_time desc
limit #{param.page},#{param.limit}

