SELECT a.discount_id AS activity_id, a.discount_name AS activity_name, DATE_FORMAT( a.discount_end_time, '%Y-%m-%d %H:%i:%S' ) AS end_time, a.shop_name, '正常' AS state_label FROM ${database.prefix.activity}hou_addon_activity_discount_base a WHERE a.discount_state = 1
and a.shop_id = #{param.shopId}
order by a.discount_start_time desc
